import { ReactFlowProvider } from 'reactflow';
import { PipelineToolbar } from './toolbar';
import { PipelineUI }      from './ui';
import { SubmitButton }    from './submit';

function App() {
  return (
    <ReactFlowProvider>
      <div style={{ display: 'flex', flexDirection: 'column', height: '100vh', background: 'var(--bg-base)', overflow: 'hidden' }}>

        {/* Top bar — Claude-style */}
        <div style={{
          height: 52,
          padding: '0 20px',
          background: 'var(--bg-elevated)',
          borderBottom: '1px solid var(--border)',
          display: 'flex',
          alignItems: 'center',
          gap: 12,
          flexShrink: 0,
          boxShadow: 'var(--shadow-sm)',
        }}>
          {/* Claude logo mark */}
          <svg width="24" height="24" viewBox="0 0 32 32" fill="none" xmlns="http://www.w3.org/2000/svg">
            <path d="M16 4C9.373 4 4 9.373 4 16s5.373 12 12 12 12-5.373 12-12S22.627 4 16 4z" fill="#c96442"/>
            <path d="M11 13.5c0-.828.672-1.5 1.5-1.5h7c.828 0 1.5.672 1.5 1.5v1c0 .828-.672 1.5-1.5 1.5h-7C11.672 16 11 15.328 11 14.5v-1zM11 18.5c0-.276.224-.5.5-.5h5c.276 0 .5.224.5.5s-.224.5-.5.5h-5c-.276 0-.5-.224-.5-.5z" fill="white"/>
          </svg>

          <div style={{ display: 'flex', flexDirection: 'column', lineHeight: 1.1 }}>
            <span style={{
              color: 'var(--text-primary)',
              fontWeight: 600,
              fontSize: 14,
              letterSpacing: -0.2,
            }}>
              VectorShift
            </span>
            <span style={{ color: 'var(--text-muted)', fontSize: 11 }}>
              Pipeline Builder
            </span>
          </div>

          <div style={{ flex: 1 }} />

          <div style={{
            fontSize: 11,
            color: 'var(--text-muted)',
            background: 'var(--bg-surface)',
            border: '1px solid var(--border)',
            borderRadius: 20,
            padding: '3px 10px',
          }}>
            Beta
          </div>
        </div>

        <PipelineToolbar />

        {/* Canvas */}
        <div style={{ flex: 1, overflow: 'hidden' }}>
          <PipelineUI />
        </div>

        <SubmitButton />
      </div>
    </ReactFlowProvider>
  );
}

export default App;
